// Build a unified context that all branches will use.
// Keep the earlier working fetch/join logic, but output compact field names
// that match B1 to B6 in the current Workflow 2.

const dbRows = $('Read Database').all().map(i => i.json);
const campaignRows = $('Read Campaigns').all().map(i => i.json);
const accountRows = $('Read Accounts').all().map(i => i.json);

const campaignsById = {};
for (const c of campaignRows) {
  campaignsById[String(c.campaign_id ?? c.campaignid ?? '').trim()] = c;
}

const accountsByName = {};
for (const a of accountRows) {
  accountsByName[String(a.account_name ?? a.accountname ?? '').trim()] = a;
}

function pick(obj, ...keys) {
  for (const k of keys) {
    if (obj && obj[k] !== undefined && obj[k] !== null) return obj[k];
  }
  return '';
}

function clean(v) {
  return (v ?? '').toString().trim();
}

function num(v, fallback = 0) {
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
}

function slugFromUrl(url) {
  if (!url) return null;
  const m = String(url).match(/\/in\/([^\/?#]+)/i);
  return m ? m[1] : null;
}

// Parse 'DD/MM/YYYY HH:mm:ss IST' to a Date
function parseIST(s) {
  if (!s) return null;
  const m = String(s).match(/(\d{2})\/(\d{2})\/(\d{4})\s+(\d{2}):(\d{2}):(\d{2})/);
  if (!m) return null;
  const [, dd, mm, yyyy, h, mi, sec] = m;
  const iso = `${yyyy}-${mm}-${dd}T${h}:${mi}:${sec}+05:30`;
  const d = new Date(iso);
  return isNaN(d.getTime()) ? null : d;
}

const now = new Date();
const out = [];

for (const row of dbRows) {
  const campaignIdRaw = pick(row, 'campaign_id', 'campaignid');
  const sendingAccountRaw = pick(row, 'sending_account', 'sendingaccount');

  const campaignid = clean(campaignIdRaw);
  const sendingaccount = clean(sendingAccountRaw);

  const campaign = campaignsById[campaignid];
  const account = accountsByName[sendingaccount];

  if (!campaign || !account) continue;

  const linkedinurl = clean(pick(row, 'linkedin_url', 'linkedinurl'));
  const message1senttime = clean(pick(row, 'message_1_sent_time', 'message1senttime'));
  const message2senttime = clean(pick(row, 'message_2_sent_time', 'message2senttime'));
  const message3senttime = clean(pick(row, 'message_3_sent_time', 'message3senttime'));
  const connectionrequesttime = clean(pick(row, 'connection_request_time', 'connectionrequesttime'));

  const connectionrequesttimeparsed = parseIST(connectionrequesttime);
  const message1senttimeparsed = parseIST(message1senttime);
  const message2senttimeparsed = parseIST(message2senttime);
  const message3senttimeparsed = parseIST(message3senttime);

  out.push({
    json: {
      // Identity
      linkedinurl,
      firstname: clean(pick(row, 'first_name', 'firstname')),
      lastname: clean(pick(row, 'last_name', 'lastname')),
      campaignid,
      campaignname: clean(pick(row, 'campaign_name', 'campaignname', 'campaignname')),
      sendingaccount,
      publicidentifier: slugFromUrl(linkedinurl),
      providerid: clean(pick(row, 'provider_id', 'providerid')),

      // Statuses
      connectionrequeststatus: clean(pick(row, 'connection_request_status', 'connectionrequeststatus')),
      connectionrequesttime,
      connectionrequesttimeparsed: connectionrequesttimeparsed ? connectionrequesttimeparsed.toISOString() : '',
      connectionaccepted: clean(pick(row, 'connection_accepted', 'connectionaccepted')),
      connectionacceptedtime: clean(pick(row, 'connection_accepted_time', 'connectionacceptedtime')),

      message1status: clean(pick(row, 'message_1_status', 'message1status')),
      message1senttime,
      message1senttimeparsed: message1senttimeparsed ? message1senttimeparsed.toISOString() : '',

      message2status: clean(pick(row, 'message_2_status', 'message2status')),
      message2senttime,
      message2senttimeparsed: message2senttimeparsed ? message2senttimeparsed.toISOString() : '',

      message3status: clean(pick(row, 'message_3_status', 'message3status')),
      message3senttime,
      message3senttimeparsed: message3senttimeparsed ? message3senttimeparsed.toISOString() : '',

      replyreceived: clean(pick(row, 'reply_received', 'replyreceived')),
      replytext: clean(pick(row, 'reply_text', 'replytext')),
      replytime: clean(pick(row, 'reply_time', 'replytime')),
      failedreason: clean(pick(row, 'failed_reason', 'failedreason')),

      // Campaign config
      campaignstatus: clean(pick(campaign, 'campaign_status', 'campaignstatus')),
      connectionnote: clean(pick(campaign, 'connection_note', 'connectionnote')),
      message1: clean(pick(campaign, 'message_1', 'message1')),
      message2: clean(pick(campaign, 'message_2', 'message2')),
      message3: clean(pick(campaign, 'message_3', 'message3')),
      message2delayhours: num(pick(campaign, 'message_2_delay_hours', 'message2delayhours'), 48),
      message3delayhours: num(pick(campaign, 'message_3_delay_hours', 'message3delayhours'), 48),

      // Account config
      accountname: clean(pick(account, 'account_name', 'accountname')),
      unipileid: clean(pick(account, 'unipile_id', 'unipileid')),
      unipileapi: clean(pick(account, 'unipile_api', 'unipileapi')),
      unipiledsn: clean(pick(account, 'unipile_dsn', 'unipiledsn')),
      accountstatus: clean(pick(account, 'status')),
      connectionssenttoday: num(pick(account, 'connections_sent_today', 'connectionssenttoday'), 0),
      connectionsdailylimit: num(pick(account, 'connections_daily_limit', 'connectionsdailylimit'), 0),
      dmssenttoday: num(pick(account, 'dms_sent_today', 'dmssenttoday'), 0),
      dmsdailylimit: num(pick(account, 'dms_daily_limit', 'dmsdailylimit'), 0),

      // Runtime
      nowiso: now.toISOString()
    }
  });
}

return out;

// Branch 1: Check connection acceptances
// Pick rows where: connectionrequeststatus='Sent' AND connectionaccepted is empty

const items = $input.all().map(i => i.json);
const out = [];

for (const p of items) {
  if (p.connectionrequeststatus !== 'Sent') continue;
  if (p.connectionaccepted) continue;
  if (!p.providerid) continue;
  if (p.accountstatus !== 'active') continue;

  out.push({ json: p });
}

return out;

const prospect = $('B1: Filter Pending Invites').item.json;
const response = $input.all().map(i => i.json);

// Flatten all pages: each item is a page like { object: 'UserRelationsList', items: [...] }
const relations = response
  .flatMap(page => Array.isArray(page.items) ? page.items : [])
  .filter(r => r && (r.member_id || r.provider_id || r.id));

const targetId = String(prospect.providerid || '').trim();

const isAccepted = relations.some(r => {
  const relationId = String(
    r.provider_id || r.member_id || r.id || ''
  ).trim();
  return relationId && relationId === targetId;
});

if (!targetId || !isAccepted) {
  // Nothing matched, return no update
  return [];
}

// Build timestamp
const now = new Date();
const opts = {
  timeZone: 'Asia/Kolkata',
  hour12: false,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
};
const parts = new Intl.DateTimeFormat('en-GB', opts).formatToParts(now);
const get = (t) => parts.find(p => p.type === t)?.value || '';
const ts = `${get('day')}/${get('month')}/${get('year')} ${get('hour')}:${get('minute')}:${get('second')} IST`;

return [
  {
    json: {
      linkedinurl: prospect.linkedinurl,
      connectionaccepted: 'Accepted',
      connectionacceptedtime: ts,
    },
  },
];

const items = $input.all().map(i => i.json);
const out = [];
const sentTodayByAccount = {};

for (const p of items) {
  if (p.connectionaccepted !== 'Accepted') continue;

  const m1 = String(p.message1status || '').trim();
  if (m1 && m1 !== 'Not Yet') continue;

  if (String(p.replyreceived || '').trim() === 'Yes') continue;
  if (!p.providerid) continue;
  if (String(p.accountstatus || '').trim() !== 'active') continue;

  const acct = String(p.sendingaccount || '').trim();
  if (!acct) continue;

  if (!(acct in sentTodayByAccount)) {
    sentTodayByAccount[acct] = Number(p.dmssenttoday || 0);
  }

  if (sentTodayByAccount[acct] >= Number(p.dmsdailylimit || 0)) continue;
  sentTodayByAccount[acct] += 1;

  out.push({
    json: {
      ...p,
      messagetosend: p.message1,
      messageslot: 1
    }
  });
}

return out;

const items = $input.all().map(i => i.json);
const out = [];
const sentTodayByAccount = {};
const nowMs = Date.now();

for (const p of items) {
  if (String(p.message1status || '').trim() !== 'Sent') continue;

  const m2 = String(p.message2status || '').trim();
  if (m2 && m2 !== 'Not Yet') continue;

  if (String(p.replyreceived || '').trim() === 'Yes') continue;
  if (!p.providerid) continue;
  if (String(p.accountstatus || '').trim() !== 'active') continue;
  if (!p.message1senttimeparsed) continue;

  const sentMs = new Date(p.message1senttimeparsed).getTime();
  if (Number.isNaN(sentMs)) continue;

  const delayMs = Number(p.message2delayhours || 48) * 60 * 60 * 1000;
  if ((nowMs - sentMs) < delayMs) continue;

  const acct = String(p.sendingaccount || '').trim();
  if (!acct) continue;

  if (!(acct in sentTodayByAccount)) {
    sentTodayByAccount[acct] = Number(p.dmssenttoday || 0);
  }

  if (sentTodayByAccount[acct] >= Number(p.dmsdailylimit || 0)) continue;
  sentTodayByAccount[acct] += 1;

  out.push({
    json: {
      ...p,
      messagetosend: p.message2,
      messageslot: 2
    }
  });
}

return out;

const items = $input.all().map(i => i.json);
const out = [];
const sentTodayByAccount = {};
const nowMs = Date.now();

for (const p of items) {
  if (String(p.message2status || '').trim() !== 'Sent') continue;

  const m3 = String(p.message3status || '').trim();
  if (m3 && m3 !== 'Not Yet') continue;

  if (String(p.replyreceived || '').trim() === 'Yes') continue;
  if (!p.providerid) continue;
  if (String(p.accountstatus || '').trim() !== 'active') continue;
  if (!p.message2senttimeparsed) continue;

  const sentMs = new Date(p.message2senttimeparsed).getTime();
  if (Number.isNaN(sentMs)) continue;

  const delayMs = Number(p.message3delayhours || 48) * 60 * 60 * 1000;
  if ((nowMs - sentMs) < delayMs) continue;

  const acct = String(p.sendingaccount || '').trim();
  if (!acct) continue;

  if (!(acct in sentTodayByAccount)) {
    sentTodayByAccount[acct] = Number(p.dmssenttoday || 0);
  }

  if (sentTodayByAccount[acct] >= Number(p.dmsdailylimit || 0)) continue;
  sentTodayByAccount[acct] += 1;

  out.push({
    json: {
      ...p,
      messagetosend: p.message3,
      messageslot: 3
    }
  });
}

return out;

const prospect = $('Split DMs').item.json;
const slot = Number(prospect.messageslot);

const now = new Date();
const opts = {
  timeZone: 'Asia/Kolkata',
  hour12: false,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit'
};

const parts = new Intl.DateTimeFormat('en-GB', opts).formatToParts(now);
const get = (t) => parts.find(p => p.type === t)?.value || '';
const ts = `${get('day')}/${get('month')}/${get('year')} ${get('hour')}:${get('minute')}:${get('second')} IST`;

const out = {
  linkedinurl: prospect.linkedinurl,
  sendingaccount: prospect.sendingaccount
};

out[`message${slot}status`] = 'Sent';
out[`message${slot}senttime`] = ts;

return [{ json: out }];

const prospect = $('Split DMs').item.json;
const accountRows = $('Read Accounts').all().map(i => i.json);

const acct = accountRows.find(a =>
  String(a.account_name || '').trim() === String(prospect.sendingaccount || '').trim()
);

if (!acct) {
  return [];
}

const current = Number(acct.dmssenttoday || 0);

return [
  {
    json: {
      accountname: acct.account_name,
      dmssenttoday: current + 1
    }
  }
];

const prospect = $('Split DMs').item.json;
const response = $input.first().json;
const slot = prospect.messageslot;

const now = new Date();
const opts = {
  timeZone: 'Asia/Kolkata',
  hour12: false,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit'
};

const parts = new Intl.DateTimeFormat('en-GB', opts).formatToParts(now);
const get = (t) => parts.find(p => p.type === t)?.value || '';
const ts = `${get('day')}/${get('month')}/${get('year')} ${get('hour')}:${get('minute')}:${get('second')} IST`;

let reason = '';
if (response.body) {
  reason = typeof response.body === 'string' ? response.body : JSON.stringify(response.body);
} else if (response.error) {
  reason = typeof response.error === 'string' ? response.error : JSON.stringify(response.error);
} else {
  reason = `HTTP ${response.statusCode || 'unknown'}`;
}

reason = `[${ts}] message${slot} failed: ${reason}`.slice(0, 500);

const out = {
  linkedinurl: prospect.linkedinurl,
  failedreason: reason
};

out[`message${slot}status`] = 'Failed';
out[`message${slot}senttime`] = ts;

return [{ json: out }];

const prospect = $('Split Reply Checks').item.json;
const chatsResp = $input.first().json;

const chats = chatsResp.items || chatsResp.data || [];

const chat = chats.find(c => {
  const attendees = c.attendees || c.attendeeproviderids || [];
  const ids = attendees.map(a =>
    typeof a === 'string' ? a : (a.provider_id || a.providerid || a.id || '')
  );
  return ids.includes(prospect.providerid);
});

if (!chat) {
  return [];
}

const last = chat.last_message || chat.lastmessage || chat.latest_message || chat.latestmessage;
if (!last) {
  return [];
}

const senderId = last.sender_id || last.senderid || last.from_provider_id || last.fromproviderid || last.author_id || last.authorid || last.provider_id || last.providerid;
const isFromProspect =
  String(senderId || '').trim() === String(prospect.providerid || '').trim() ||
  last.is_sender === false ||
  last.issender === false ||
  last.from_me === false ||
  last.fromme === false;

if (!isFromProspect) {
  return [];
}

const replyText = last.text || last.body || last.content || '';
const replyTimeRaw = last.timestamp || last.created_at || last.createdat || last.date || '';

let replyTime = '';
if (replyTimeRaw) {
  const d = new Date(replyTimeRaw);
  if (!Number.isNaN(d.getTime())) {
    const opts = {
      timeZone: 'Asia/Kolkata',
      hour12: false,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
    };
    const parts = new Intl.DateTimeFormat('en-GB', opts).formatToParts(d);
    const get = (t) => parts.find(p => p.type === t)?.value || '';
    replyTime = `${get('day')}/${get('month')}/${get('year')} ${get('hour')}:${get('minute')}:${get('second')} IST`;
  }
}

return [
  {
    json: {
      linkedinurl: prospect.linkedinurl,
      replyreceived: 'Yes',
      replytext: String(replyText).slice(0, 500),
      replytime: replyTime
    }
  }
];

const prospect = $('Split Reply Checks').item.json;
const chatsResp = $input.first().json;
const chats = chatsResp.items || chatsResp.data || [];

// Find chat matching the prospect
const chat = chats.find(c => {
  const ids = (c.attendees || c.attendeeproviderids || []).map(a =>
    typeof a === 'string' ? a : (a.providerid || a.id)
  );
  return ids.includes(prospect.providerid);
});

if (!chat) return [];

// Get last message details
const last = chat.lastmessage || chat.latestmessage;
if (!last) return [];

// Determine if last message is from the prospect
const senderId = last.senderid || last.fromproviderid || last.authorid || last.providerid;
const isFromProspect =
  senderId === prospect.providerid ||
  last.issender === false ||
  last.fromme === false;

if (!isFromProspect) return [];

const replyText = last.text || last.body || last.content || '';
const replyTimeRaw = last.timestamp || last.createdat || last.date;

// Format replytime as IST
let replyTime = '';
if (replyTimeRaw) {
  const d = new Date(replyTimeRaw);
  if (!isNaN(d.getTime())) {
    const opts = {
      timeZone: 'Asia/Kolkata',
      hour12: false,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    };
    const parts = new Intl.DateTimeFormat('en-GB', opts).formatToParts(d);
    const get = (t) => parts.find(p => p.type === t)?.value || '';
    replyTime = `${get('day')}/${get('month')}/${get('year')} ${get('hour')}:${get('minute')}:${get('second')} IST`;
  }
}

return [
  {
    json: {
      linkedinurl: prospect.linkedinurl,
      replyreceived: 'Yes',
      replytext: String(replyText).slice(0, 500),
      replytime: replyTime
    }
  }
];

const items = $input.all().map(i => i.json);
const out = [];
const nowMs = Date.now();
const sevenDaysMs = 7 * 24 * 60 * 60 * 1000;

for (const p of items) {
  if (String(p.connectionrequeststatus || '').trim() !== 'Sent') continue;
  if (String(p.connectionaccepted || '').trim()) continue;
  if (!p.connectionrequesttimeparsed) continue;
  if (!p.providerid) continue;

  const reqMs = new Date(p.connectionrequesttimeparsed).getTime();
  if (Number.isNaN(reqMs)) continue;

  if ((nowMs - reqMs) < sevenDaysMs) continue;

  out.push({ json: p });
}

return out;

const prospect = $('Split Expiries').item.json;
const response = $input.first().json;
const invites = response.items || response.data || [];

const match = invites.find(i =>
  (i.recipientproviderid || i.providerid || i.recipientid) === prospect.providerid
);

if (!match) {
  return [
    {
      json: {
        ...prospect,
        invitationid: null,
        skipwithdraw: true
      }
    }
  ];
}

return [
  {
    json: {
      ...prospect,
      invitationid: match.id || match.invitationid,
      skipwithdraw: false
    }
  }
];

const prospect = $('Split Expiries').item.json;

const now = new Date();
const opts = {
  timeZone: 'Asia/Kolkata',
  hour12: false,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit'
};

const parts = new Intl.DateTimeFormat('en-GB', opts).formatToParts(now);
const get = (t) => parts.find(p => p.type === t)?.value || '';
const ts = `${get('day')}/${get('month')}/${get('year')} ${get('hour')}:${get('minute')}:${get('second')} IST`;

return [
  {
    json: {
      linkedinurl: prospect.linkedinurl,
      connectionrequeststatus: 'Expired',
      failedreason: `[${ts}] No acceptance after 7 days; invite withdrawn`
    }
  }
];
